<?php
require_once __DIR__.'/../api-auth.php';require_once __DIR__.'/../../../config/config.php';require_once __DIR__.'/../../../includes/student-communication-api.php';
$student=requireApiStudent($pdo);$userId=(int)$student['user_id'];$studentId=(int)$student['student_id'];$method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');
try{
 if($method==='GET'){$limit=studentCommunicationLimit($_GET['limit']??30);$offset=max(0,(int)($_GET['offset']??0));$items=studentConversationList($pdo,$userId,$limit,$offset);apiResponse(true,'',['items'=>$items,'limit'=>$limit,'offset'=>$offset]);}
 if($method==='POST'){$input=apiInput();$subject=trim((string)($input['subject']??''));$recipients=studentCommunicationResolveRecipients($pdo,$userId,$studentId,is_array($input['recipient_user_ids']??null)?$input['recipient_user_ids']:[]);if($subject===''||mb_strlen($subject)>255||!$recipients)apiResponse(false,'Objet ou destinataires invalides.',[],422);$uuid=communicationUlid();$org=studentCommunicationOrganisation($pdo,$studentId);$pdo->beginTransaction();$pdo->prepare('INSERT INTO conversations(identifiant_public,type_conversation,objet,cree_par_utilisateur_id) VALUES(?,?,?,?)')->execute([$uuid,count($recipients)>1?'groupe':'privee',$subject,$userId]);$id=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO participants_conversations(conversation_id,utilisateur_id,organisation_representation_id) VALUES(?,?,?)');$q->execute([$id,$userId,$org]);foreach($recipients as $recipient){$q->execute([$id,$recipient,null]);communicationNotifier($pdo,$recipient,$org,'nouvelle_conversation','Nouvelle conversation',$subject,rtrim(BASE_URL,'/').'/api/v1/student/conversations/'.$uuid.'/messages',['conversation_uuid'=>$uuid,'action'=>['type'=>'conversation','target_id'=>$uuid,'label'=>'Ouvrir la discussion','title'=>$subject,'metadata'=>[]]]);}$pdo->commit();apiResponse(true,'Conversation creee.',['conversation'=>['uuid'=>$uuid,'type'=>count($recipients)>1?'groupe':'privee','subject'=>$subject,'recipient_count'=>count($recipients)]],201);}
 header('Allow: GET, POST');apiResponse(false,'Methode HTTP non autorisee.',[],405);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[API CONVERSATIONS] '.$e->getMessage());apiResponse(false,'Impossible de gerer les conversations.',[],500);}
